-- Forsaken origins. DRAFT for the user's approval. Year 1: Sylvanas freed them from the Lich
-- King; the Undercity is beneath Lordaeron's ruins. Who they were in life still marks them.
local P = RPGDialogueAPI:Pack("rpgd.world")

P:Origin {
  id = "forsaken", race = "Scourge",
  origins = {
    { id = "forsaken_lordaeron_soldier", name = "Once a soldier of Lordaeron",
      blurb = "I wore Terenas's colors when the plague came, and I died holding a gate that didn't matter. Now I serve the Dark Lady, and I've stopped asking which of them deserved it more.",
      nudge = { trait = { stern = 1 }, align = { order = 1 } }, home = "undercity" },
    { id = "forsaken_brill_farmer", name = "Once a farmer near Brill",
      blurb = "I grew barley outside Brill and ate the plagued grain like everyone else. The field's still there; I walk past it sometimes and feel nothing, and that frightens me more than anything.",
      nudge = { trait = { cautious = 1 } }, home = "brill" },
    { id = "forsaken_scourge_remembered", name = "Remembers serving the Scourge",
      blurb = "I remember everything I did while the Lich King held me, every village and every face. The Dark Lady says it wasn't me, and I'd like very much to believe her.",
      nudge = { trait = { stern = 1 }, align = { light = -1 } } },
    { id = "forsaken_dalaran_apprentice", name = "Once an apprentice of Dalaran", class = "MAGE",
      blurb = "I studied in the violet city before Archimonde flattened it, and my notes rotted in the rubble with the rest of me. The spells came back when I did, though my patience for students stayed in the grave.",
      nudge = { trait = { curious = 1 } }, home = "undercity" },
    { id = "forsaken_chapel_priest", name = "Once a priest of Lordaeron's chapels", class = "PRIEST",
      blurb = "I gave sermons on the Light to farmers who are now ghouls. The Light still answers me, though it hurts, and I've decided to treat the pain as the Light talking back.",
      nudge = { trait = { pious = 1 }, align = { light = 1 } } },
    { id = "forsaken_risen_knight", name = "A Silver Hand knight, risen", class = "PALADIN",
      blurb = "I took the oath in Uther's day and died in Lordaeron when the oath meant nothing. I still say the words, and the Light still comes, and neither of us understands why.",
      nudge = { trait = { pious = 1 }, align = { light = 2, honor = 1 } } },
    { id = "forsaken_deathstalker_recruit", name = "Deathstalker recruit", class = "ROGUE",
      blurb = "The Dark Lady's deathstalkers go where the living can't and the dead shouldn't. They took me because I'd been dead long enough to stop being afraid of it.",
      nudge = { trait = { cautious = 1 }, align = { honor = -1, order = 1 } }, home = "undercity" },
    { id = "forsaken_cult_remnant", name = "Cult of the Damned, before death", class = "WARLOCK",
      blurb = "I joined the Cult of the Damned while I was alive, and I knew what they were. The Forsaken let me in anyway, because they need what I know, and they never let me forget why I know it.",
      nudge = { trait = { cruel = 1 }, align = { light = -2 } } },
    { id = "forsaken_scarlet_turned", name = "Once a soldier of the Scarlet Crusade", class = "WARRIOR",
      blurb = "I marched with the Scarlet Crusade and burned plague victims in Tirisfal until the plague took me too. Now my old brothers in red hunt me through the same fields, and I've learned to swing first.",
      nudge = { trait = { stern = 1 }, align = { light = -1, order = -1 } }, home = "brill" },
    { id = "forsaken_hillsbrad_militia", name = "Once in the Hillsbrad militia", class = "WARRIOR",
      blurb = "I was a militia volunteer in Hillsbrad, with a pitchfork and a borrowed helmet, when the undead came over the hills. Tarren Mill belongs to the Forsaken now and I stand its watch, which is either justice or a very bad joke.",
      nudge = { trait = { witty = 1 }, align = { order = 1, honor = 1 } }, home = "tarren_mill" },
    { id = "forsaken_capital_cutpurse", name = "Once a cutpurse in Lordaeron's capital", class = "ROGUE",
      blurb = "I picked pockets in Lordaeron's market when there was still a market to pick. I do the same in the Undercity, though the pockets are emptier and the owners notice less.",
      nudge = { trait = { greedy = 1, witty = 1 }, align = { order = -1 } }, home = "undercity" },
    { id = "forsaken_shadow_acolyte", name = "Acolyte of the shadow", class = "PRIEST",
      blurb = "The Light abandoned Lordaeron, so I stopped waiting for it to come back. The priests of the Undercity taught me that shadow answers prayers too, and it never asks whether you deserved the answer.",
      nudge = { trait = { skeptical = 1 }, align = { light = -1, order = 1 } }, home = "undercity" },
    { id = "forsaken_stratholme_archivist", name = "Once an archivist in Stratholme", class = "MAGE",
      blurb = "I kept the archives in Stratholme until the Culling, and I never learned whether Arthas spared the books. The arcane came easily once I rose, as if death had cleared some room in my head.",
      nudge = { trait = { curious = 1 }, align = { order = 1 } } },
    { id = "forsaken_vengeful_binder", name = "Bound demons for vengeance", class = "WARLOCK",
      blurb = "When I woke in Deathknell, all I wanted was a way to hurt the Lich King back. The Undercity's warlocks offered me one, and the demons they bind don't seem to mind that I'm already dead.",
      nudge = { trait = { cruel = 1 }, align = { light = -1, honor = -1 } }, home = "deathknell" },
    { id = "forsaken_unsworn_squire", name = "A squire who never took the oath", class = "PALADIN",
      blurb = "I was a squire in Andorhal when the grain carts came, and I died before I could take my oath. I swear it now every morning, and every morning the Light scorches me, and I keep swearing.",
      nudge = { trait = { brave = 1 }, align = { light = 2, order = 1 } } },
    { id = "forsaken_silverpine_woodsman", name = "Once a Silverpine woodsman",
      blurb = "I cut timber in Silverpine Forest and drank in Pyrewood before the plague and Arugal's worgen ruined both. The Sepulcher is as close to home as I'll get now, and the trees still look the same.",
      nudge = { trait = { skeptical = 1 }, align = { order = 1 } }, home = "sepulcher" },
    { id = "other", name = "Other" },
  },
}
